{
  "title": "Discussion about living and working abroad in Slovakia and Austria",
  "topics": [
    {
      "id": "expatriates-in-slovakia",
      "title": "People living or interested in living in Slovakia",
      "claims": [
        {
          "text": "There are members living in Bratislava or elsewhere in Slovakia, and some have moved abroad",
          "evidence": [1, 2]
        },
        {
          "text": "One participant has been in Slovakia for almost a year and does not know the language",
          "evidence": [43]
        },
        {
          "text": "Another participant lives in Austria since November 2025 and arrived in September 2025",
          "evidence": [49, 54]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Finding jobs abroad and application experience",
      "claims": [
        {
          "text": "Two acquaintances are in Austria and Poland respectively",
          "evidence": [3]
        },
        {
          "text": "One user applied to about 100 jobs and got only 3 interviews",
          "evidence": [21]
        },
        {
          "text": "The user succeeded in finding a job within 2 months despite difficulty",
          "evidence": [17]
        },
        {
          "text": "LinkedIn is recommended for job searching",
          "evidence": [18]
        },
        {
          "text": "Most vacancy listings require local language proficiency, often B2 level",
          "evidence": [26, 46]
        },
        {
          "text": "Despite language requirements, some candidates with limited language skills are still hired",
          "evidence": [29]
        },
        {
          "text": "Salary for the described position was higher than a minimum wage but still low",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language needs for work and daily life",
      "claims": [
        {
          "text": "German is the primary language used in Austria, but English is also common in workplaces",
          "evidence": [14, 15, 44]
        },
        {
          "text": "Neighbors speak Ukrainian, creating a multilingual environment",
          "evidence": [45]
        },
        {
          "text": "B2 is the most frequently requested language level; B1 may be acceptable without certification",
          "evidence": [46]
        },
        {
          "text": "Personal language learning started recently due to discomfort in daily interactions",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "salary-and-experience",
      "title": "Salary expectations and experience levels",
      "claims": [
        {
          "text": "With 3 years of experience, the user received a higher salary than a fast-food job but considered it minimal",
          "evidence": [37]
        },
        {
          "text": "Even candidates with only a master's degree and no commercial experience can get mid‑level interview calls",
          "evidence": [28]
        }
      ]
    },
    {
      "id": "future-plans",
      "title": "Future relocation considerations",
      "claims": [
        {
          "text": "One participant is considering moving to Warsaw for a tech event",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Should I stay in Austria? (personal feeling about remaining in Austria)",
      "evidence": [58]
    }
  ]
}
